217	    /**
218	     * Builds the derived identity key that consolidates all owner duplicate detection into a
219	     * single value: the normalized E.164 {@code telephone}, the lower-cased {@code email}
220	     * (empty when none) and the {@code householdId} (empty when the owner shares no household),
221	     * joined by {@code '|'}. Two owners are duplicates exactly when their whole identity keys are
222	     * equal, so a difference in any of the three parts (for example two household mates with
223	     * different telephones) yields distinct keys. A {@code null} part contributes the empty string.
224	     *
225	     * @param telephone the normalized E.164 telephone
226	     * @param email the lower-cased email, or {@code null} when none
227	     * @param householdId the shared household identifier, or {@code null} when none
228	     * @return the derived identity key
229	     */
230	    public static String identityKey(String telephone, String email, String householdId) {
231	        return (telephone == null ? "" : telephone) + "|"
232	            + (email == null ? "" : email) + "|"
233	            + (householdId == null ? "" : householdId);
234	    }
235	
236	    /**
237	     * Returns this owner's derived identity key, see
238	     * {@link #identityKey(String, String, String)}.
239	     *
240	     * @return the derived identity key for this owner
241	     */
242	    @Transient
243	    public String getIdentityKey() {
244	        return identityKey(this.telephone, this.email, this.householdId);
245	    }
246	
247	    /**
248	     * Fixed telephone country-code table: the exact national-number length (the count of digits
249	     * following the country code) each country code this application recognizes admits
250	     * ({@code '61'} Australia => 9, {@code '1'} NANP => 10). Keyed by the country-code digits
251	     * without the leading {@code '+'}. A country code absent from this table is not recognized.
252	     */
253	    private static final Map<String, Integer> COUNTRY_CODE_NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
254	
255	    /**
256	     * Resolves the recognized country code a normalized E.164 telephone carries: the longest entry
257	     * of the fixed country-code table (see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}) whose digits the
258	     * number begins with, so a shorter code can never shadow a longer one. Returns the country-code
259	     * digits without the leading {@code '+'} (for example {@code '61'} for {@code '+61412345678'}),
260	     * or {@code null} when the value is {@code null}, carries no leading {@code '+'}, or begins with
261	     * no recognized country code. This is the single definition of how an E.164 telephone splits
262	     * from its country code, shared by every rule that reasons about a telephone's country code.
263	     *
264	     * @param telephone the normalized E.164 telephone (a {@code '+'} followed by digits), or {@code null}
265	     * @return the recognized country-code digits, or {@code null} when none is recognized
266	     */
267	    public static String countryCodeOf(String telephone) {
268	        if (telephone == null || !telephone.startsWith("+")) {
269	            return null;
270	        }
271	        String digits = telephone.substring(1);
272	        return COUNTRY_CODE_NATIONAL_LENGTHS.keySet().stream()
273	            .filter(digits::startsWith)
274	            .max(Comparator.comparingInt(String::length))
275	            .orElse(null);
276	    }
277	
278	    /**
279	     * Resolves the exact national-number length (the count of digits following the country code) a
280	     * recognized country code admits using the fixed country-code table ({@code '61'} => 9,
281	     * {@code '1'} => 10, see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}). Returns the length, or
282	     * {@code null} when the country code is {@code null} or not recognized (it then carries no
283	     * per-country length rule). This is the single definition of the per-country national-number
284	     * lengths, shared by every rule that relates a telephone's national number to its country code.
285	     *
286	     * @param countryCode the country-code digits without the leading {@code '+'}, or {@code null}
287	     * @return the required national-number length, or {@code null} when the code is not recognized
288	     */
289	    public static Integer nationalNumberLength(String countryCode) {
290	        return countryCode == null ? null : COUNTRY_CODE_NATIONAL_LENGTHS.get(countryCode);
291	    }
292	
293	    /**
294	     * Fixed city-to-region table: the canonical region each known city belongs to
295	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). A city
296	     * absent from this table has no known region.
297	     */
298	    private static final Map<String, String> CITY_REGIONS = Map.of(
299	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
300	
301	    /**
302	     * Resolves the canonical region a city belongs to using the fixed city-to-region table
303	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Returns the
304	     * region string, or {@code null} when the city has no known region. This is the single
305	     * definition of the city-to-region mapping, shared by every rule that derives a region
306	     * from an owner's city.
307	     *
308	     * @param city the city to resolve
309	     * @return the canonical region, or {@code null} when the city has no known region
310	     */
311	    public static String regionForCity(String city) {
312	        return CITY_REGIONS.get(city);
313	    }
314	
315	    /**
316	     * Fixed region-to-postcode table: the inclusive {@code {low, high}} 4-digit postcode range
317	     * each region admits ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
318	     * A region absent from this table has no fixed range.
319	     */
320	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
321	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
322	
323	    /**
324	     * Resolves the inclusive {@code {low, high}} 4-digit postcode range a region admits using the
325	     * fixed region-to-postcode table ({@code NSW 2000-2099}, {@code VIC 3000-3099},
326	     * {@code QLD 4000-4099}). Returns the range, or {@code null} when the region is {@code null} or
327	     * has no fixed range (any 4-digit postcode is then admitted). This is the single definition of
328	     * the region-to-postcode ranges, shared by every rule that relates a postcode to a region.
329	     *
330	     * @param region the region to resolve, or {@code null}
331	     * @return the inclusive {@code {low, high}} range, or {@code null} when the region has none
332	     */
333	    public static int[] postcodeRangeForRegion(String region) {
334	        return region == null ? null : REGION_POSTCODE_RANGES.get(region);
335	    }
336	
337	    /**
338	     * Resolves the canonical region a postcode belongs to by finding the fixed region-to-postcode
339	     * range that contains it ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
340	     * Returns the region string, or {@code null} when the postcode is {@code null}, not a 4-digit
341	     * value, or falls in no known range. This is the single definition of the postcode-to-region
342	     * mapping, shared by every rule that derives a region from a postcode.
343	     *
344	     * @param postcode the postcode to resolve
345	     * @return the canonical region, or {@code null} when the postcode maps to no known region
346	     */
347	    public static String regionForPostcode(String postcode) {
348	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
349	            return null;
350	        }
351	        int value = Integer.parseInt(postcode);
352	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
353	            int[] range = entry.getValue();
354	            if (value >= range[0] && value <= range[1]) {
355	                return entry.getKey();
356	            }
357	        }
358	        return null;
359	    }
360	
361	    /**
362	     * Returns the canonical region this owner belongs to. The owner's {@code postcode} is preferred:
363	     * when it falls in a known region range (see {@link #regionForPostcode(String)}) that region is
364	     * used, disambiguating cities that share a name. Only when the postcode is absent or in no known
365	     * range does derivation fall back to the fixed city-to-region table (see
366	     * {@link #regionForCity(String)}). Returns {@code null} when neither the postcode nor the city
367	     * resolves to a known region. This is the single definition of an owner's region, shared by
368	     * every rule that derives a region from an owner.
369	     *
370	     * @return the owner's canonical region, or {@code null} when it has no known region
371	     */
372	    @Transient
373	    public String getRegion() {
374	        String region = regionForPostcode(this.postcode);
375	        return region != null ? region : regionForCity(this.city);
376	    }
377	
378	    /**
379	     * Resolves whether an {@code email} counts as present for membership purposes: the value is
380	     * non-null and not blank. Returns {@code false} otherwise. This is the single definition of an
381	     * owner "having an email", shared by every rule that turns email presence into a derived value
382	     * (its membership factor and its {@code contactPreference}).
383	     *
384	     * @param email the owner's email, or {@code null}
385	     * @return {@code true} when the email is present and not blank
386	     */
387	    public static boolean hasEmail(String email) {
388	        return email != null && !email.isBlank();
389	    }
390	
391	    /**
392	     * Resolves whether an owner with the given {@code namesakeCount} has no namesakes: the count is
393	     * present and equal to {@code 0}. Returns {@code false} when the count is {@code null} (unknown)
394	     * or positive. This is the single definition of the "no namesakes" membership factor, shared by
395	     * every rule that rewards an owner for being unique by name.
396	     *
397	     * @param namesakeCount the owner's namesake count, or {@code null}
398	     * @return {@code true} when the owner is known to have no namesakes
399	     */
400	    public static boolean hasNoNamesakes(Integer namesakeCount) {
401	        return namesakeCount != null && namesakeCount == 0;
402	    }
403	
404	    /**
405	     * Resolves whether an owner registered on {@code registrationDate} has long tenure as of
406	     * {@code asOf}: the whole number of days between the two dates exceeds {@code 365}. Returns
407	     * {@code false} when {@code registrationDate} is absent, so the owner has no derivable tenure;
408	     * because a newly created owner has zero tenure, it never counts as long-tenured. This is the
409	     * single definition of the "long tenure" membership factor, shared by every rule that rewards
410	     * an owner for tenure beyond a year.
411	     *
412	     * @param registrationDate the owner's registration date, or {@code null}
413	     * @param asOf the date the tenure is measured against
414	     * @return {@code true} when the owner's tenure exceeds 365 days
415	     */
416	    public static boolean hasLongTenure(LocalDate registrationDate, LocalDate asOf) {
417	        return registrationDate != null && ChronoUnit.DAYS.between(registrationDate, asOf) > 365;
418	    }
419	
420	    /**
421	     * Resolves whether an owner with the given {@code householdMemberCount} belongs to a large
422	     * household: the count is present and at least {@code 3}. Returns {@code false} when the count is
423	     * {@code null} (unknown) or smaller. This is the single definition of the "large household"
424	     * membership factor, shared by every rule that rewards an owner for a household of three or more.
425	     *
426	     * @param householdMemberCount the number of owners sharing the household, or {@code null}
427	     * @return {@code true} when the owner is known to belong to a household of three or more
428	     */
429	    public static boolean hasLargeHousehold(Integer householdMemberCount) {
430	        return householdMemberCount != null && householdMemberCount >= 3;
431	    }
432	
433	    /**
434	     * Returns this owner's membership points. Points start at {@code 0} and accumulate the membership
435	     * factors: {@code 2} when an email is present, {@code 1} when the owner has no namesakes
436	     * (namesakeCount is 0), {@code 2} when the owner belongs to a household of three or more, and
437	     * {@code 3} when the owner's tenure exceeds 365 days. Because a newly created owner has zero
438	     * tenure, the tenure points are never awarded on creation. This is the single source the
439	     * membership level is derived from (see {@link #getMembershipLevel()}).
440	     *
441	     * @return the owner's membership points
442	     */
443	    @Transient
444	    public Integer getMembershipPoints() {
445	        LocalDate today = LocalDate.now();
446	        int points = 0;
447	        if (hasEmail(this.email)) {
448	            points += 2;
449	        }
450	        if (hasNoNamesakes(this.namesakeCount)) {
451	            points += 1;
452	        }
453	        if (hasLargeHousehold(this.householdMemberCount)) {
454	            points += 2;
455	        }
456	        if (hasLongTenure(this.registrationDate, today)) {
457	            points += 3;
458	        }
459	        return points;
460	    }
461	
462	    /**
463	     * Returns this owner's numeric membership level, derived from its membership points (see
464	     * {@link #getMembershipPoints()}): {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3},
465	     * {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more points.
466	     *
467	     * @return the owner's membership level
468	     */
469	    @Transient
470	    public Integer getMembershipLevel() {
471	        int points = getMembershipPoints();
472	        if (points >= 6) {
473	            return 4;
474	        }
475	        if (points >= 4) {
476	            return 3;
477	        }
478	        if (points >= 2) {
479	            return 2;
480	        }
481	        return 1;
482	    }
483	
484	    /**
485	     * Returns this owner's membership number formatted as {@code '<customerCode>-M<YY>'}, where YY is
486	     * the last two digits of the registrationDate year, e.g. {@code 'NSW-A1B2C3D4-M26'}. Returns
487	     * {@code null} when the owner has no customer code or registration date.
488	     *
489	     * @return the owner's membership number, or {@code null} when it cannot be derived
490	     */
491	    @Transient
492	    public String getMembershipNumber() {
493	        if (this.customerCode == null || this.registrationDate == null) {
494	            return null;
495	        }
496	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
497	    }
498	
499	    /**
500	     * Returns this owner's check digit: a single Luhn check digit (0-9) over the digits contained in
501	     * the owner's customerCode. Returns {@code null} when the owner has no customer code.
502	     *
503	     * @return the owner's check digit, or {@code null} when it has no customer code
504	     */
505	    @Transient
506	    public Integer getCheckDigit() {
507	        if (this.customerCode == null) {
508	            return null;
509	        }
510	        String code = this.customerCode;
511	        int sum = 0;
512	        boolean dbl = true;
513	        for (int i = code.length() - 1; i >= 0; i--) {
514	            char c = code.charAt(i);
515	            if (c < '0' || c > '9') {
516	                continue;
517	            }
518	            int d = c - '0';
519	            if (dbl) {
520	                d *= 2;
521	                if (d > 9) {
522	                    d -= 9;
523	                }
524	            }
525	            sum += d;
526	            dbl = !dbl;
527	        }
528	        return (10 - (sum % 10)) % 10;
529	    }
530	
531	    /**
532	     * Returns this owner's age band, derived from {@code birthDate} computed against
533	     * {@code registrationDate}: the whole number of years between the two dates places the owner in
534	     * {@code 'MINOR'} (under 18), {@code 'ADULT'} (18 to 64 inclusive) or {@code 'SENIOR'} (65 or
535	     * older). Returns {@code null} when the owner has no birth date or no registration date, so the
536	     * band cannot be derived. This is the single definition of an owner's age band.
537	     *
538	     * @return the owner's age band, or {@code null} when it cannot be derived
539	     */
540	    @Transient
541	    public String getAgeBand() {
542	        if (this.birthDate == null || this.registrationDate == null) {
543	            return null;
544	        }
545	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
546	        if (age < 18) {
547	            return "MINOR";
548	        }
549	        if (age < 65) {
550	            return "ADULT";
551	        }
552	        return "SENIOR";
553	    }
