494	    /**
495	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
496	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
497	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
498	     * the names of every offending field, which the exception advice renders as a 400 response
499	     * with an {@code errors} array.
500	     *
501	     * @param ownerFieldsDto the submitted owner fields
502	     */
503	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
504	        List<String> missing = new ArrayList<>();
505	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
506	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
507	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
508	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
509	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
510	        if (!missing.isEmpty()) {
511	            throw new RequiredFieldsMissingException(missing);
512	        }
513	    }
514	
515	    private void addIfBlank(List<String> missing, String fieldName, String value) {
516	        if (value == null || value.isBlank()) {
517	            missing.add(fieldName);
518	        }
519	    }
520	
521	    /**
522	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
523	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
524	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
525	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
526	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
527	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
528	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
529	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
530	     *
531	     * @param telephone the submitted telephone value
532	     * @return the normalized E.164 telephone
533	     */
534	    private String normalizeTelephone(String telephone) {
535	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
536	        String e164;
537	        if (cleaned.startsWith("+")) {
538	            e164 = "+" + cleaned.substring(1);
539	        } else {
540	            String national = cleaned;
541	            if (national.startsWith("0")) {
542	                national = national.substring(1);
543	            }
544	            e164 = "+61" + national;
545	        }
546	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
547	            throw new InvalidFieldsException(List.of("telephone"));
548	        }
549	        validateNationalNumberLength(e164);
550	        return e164;
551	    }
552	
553	    /**
554	     * Validates the national-number length of an already syntactically valid E.164 telephone
555	     * against its country code. When the number carries a country code this application recognizes
556	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
557	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
558	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
559	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
560	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
561	     * that is not recognized carries no per-country length rule and is left to the general
562	     * 8-to-15-digit E.164 check.
563	     *
564	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
565	     */
566	    private void validateNationalNumberLength(String e164) {
567	        String countryCode = Owner.countryCodeOf(e164);
568	        if (countryCode == null) {
569	            return;
570	        }
571	        int nationalLength = e164.length() - 1 - countryCode.length();
572	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
573	            throw new InvalidFieldsException(List.of("telephone"));
574	        }
575	    }
576	
577	    /**
578	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
579	     * and a domain containing at least one dot, none of the parts holding whitespace or a
580	     * second {@code @}.
581	     */
582	    private static final java.util.regex.Pattern EMAIL_PATTERN =
583	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
584	
585	    /**
586	     * Disposable email domains an owner may not register with. An email whose domain (compared
587	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
588	     */
589	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
590	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
591	
592	    /**
593	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
594	     * accepted and returned unchanged. When present it must be a syntactically valid address
595	     * whose domain is not on the disposable-domain blocklist (see
596	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
597	     * present but syntactically invalid or on a disposable domain an
598	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
599	     * response naming the {@code email} field.
600	     *
601	     * @param email the submitted email value, or {@code null} when omitted
602	     * @return the lower-cased email, or {@code null} when none was supplied
603	     */
604	    private String normalizeEmail(String email) {
605	        if (email == null) {
606	            return null;
607	        }
608	        String trimmed = email.trim();
609	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
610	            throw new InvalidFieldsException(List.of("email"));
611	        }
612	        String domain = trimmed.substring(trimmed.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
613	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
614	            throw new InvalidFieldsException(List.of("email"));
615	        }
616	        return canonicalEmail(trimmed);
617	    }
618	
619	    /**
620	     * Reduces an email to the canonical form used both to store it and to compare it against
621	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
622	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
623	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
624	     * value read back off an existing owner without risk of rejecting it. This is the single
625	     * definition of email identity: two emails denote the same address exactly when they
626	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
627	     * an email already on an existing owner can be compared for equality after both pass through
628	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
629	     *
630	     * @param email the email to canonicalize, or {@code null} when none was supplied
631	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
632	     */
633	    private String canonicalEmail(String email) {
634	        if (email == null) {
635	            return null;
636	        }
637	        return email.trim().toLowerCase(java.util.Locale.ROOT);
638	    }
639	
640	    /**
641	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
642	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
643	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
644	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
645	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
646	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
647	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
648	     * 400 response naming the {@code postcode} field.
649	     *
650	     * @param postcode the submitted postcode, or {@code null} when omitted
651	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
652	     */
653	    private void validatePostcode(String postcode, String city) {
654	        if (postcode == null) {
655	            return;
656	        }
657	        if (!postcode.matches("^[0-9]{4}$")) {
658	            throw new InvalidFieldsException(List.of("postcode"));
659	        }
660	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
661	        if (range != null) {
662	            int value = Integer.parseInt(postcode);
663	            if (value < range[0] || value > range[1]) {
664	                throw new InvalidFieldsException(List.of("postcode"));
665	            }
666	        }
667	    }
668	
669	    /**
670	     * Rejects a new owner that would join a household already occupied by an existing owner. The
671	     * household is keyed on {@code (lastName, postcode)} and identified by the deterministic
672	     * {@code householdId} the owner would receive (see {@link #householdIdFor(String, String)}), so
673	     * two owners sharing a last name and postcode belong to the same household. When any existing
674	     * owner already carries that household identifier the new owner is a household duplicate and a
675	     * {@link DuplicateIdentityException} is thrown, which the exception advice renders as a 409
676	     * Conflict response. Setting {@code sharesHousehold} declares the owner a deliberate member of
677	     * that household and bypasses this block, so it is created rather than rejected. An owner without
678	     * a postcode belongs to no shared household and is never a household duplicate.
679	     *
680	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
681	     */
682	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
683	        if (sharesHousehold(ownerFieldsDto)) {
684	            return;
685	        }
686	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
687	        if (householdId == null) {
688	            return;
689	        }
690	        boolean taken = this.clinicService.findAllOwners().stream()
691	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
692	        if (taken) {
693	            throw new DuplicateIdentityException(householdId);
694	        }
695	    }
696	
697	    /**
698	     * Assigns the deterministic shared {@code householdId} to a newly created owner. The identifier
699	     * is derived from the owner's household identity — its {@code lastName} and {@code postcode} (see
700	     * {@link #householdIdFor(String, String)}) — so every owner sharing a last name and postcode
701	     * resolves to the same stable value automatically, without any explicit linking. An owner without
702	     * a postcode belongs to no shared household and is left without a household identifier.
703	     *
704	     * @param owner the newly created owner, mutated in place with its household identifier
705	     */
706	    private void assignHousehold(Owner owner) {
707	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
708	    }
709	
710	    /**
711	     * Reports whether a submitted owner opted into sharing a household, i.e. whether its request
712	     * carried {@code sharesHousehold} set to {@code true}. A {@code null} or {@code false} flag is
713	     * not opting in. This is the single reading of the {@code sharesHousehold} intent, shared by
714	     * every rule that treats a declared household member differently from an independent owner.
715	     *
716	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
717	     * @return {@code true} when the request opted into sharing a household
718	     */
719	    private boolean sharesHousehold(OwnerFieldsDto ownerFieldsDto) {
720	        return Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
721	    }
722	
723	    /**
724	     * Derives the stable {@code householdId} shared by every owner in the household identified by
725	     * the given {@code lastName} and {@code postcode}. The household is keyed on {@code (lastName,
726	     * postcode)}: the normalized last name and the postcode are hashed with SHA-256 and the leading
727	     * 12 hex characters of the digest form the identifier, so any two owners sharing a last name and
728	     * postcode — regardless of creation order or address — resolve to the same identifier
729	     * automatically. An owner without a postcode belongs to no shared household, so {@code null} is
730	     * returned.
731	     *
732	     * @param lastName the household's last name
733	     * @param postcode the household's postcode, or {@code null} when the owner has none
734	     * @return the deterministic household identifier, or {@code null} when {@code postcode} is {@code null}
735	     */
736	    private String householdIdFor(String lastName, String postcode) {
737	        if (postcode == null) {
738	            return null;
739	        }
740	        return shaHex(householdKey(lastName, postcode), 12);
741	    }
742	
743	    /**
744	     * Builds the canonical household key that identifies the household a {@code lastName} and
745	     * {@code postcode} belong to: the normalized last name (case-insensitive, with collapsed
746	     * whitespace) joined to the postcode by {@code '|'}. This is the single definition of which
747	     * owner fields make up a household and how they are normalized;
748	     * {@link #householdIdFor(String, String)} hashes this key into the stored identifier, so any two
749	     * owners in the same household resolve to the same key and therefore the same identifier.
750	     *
751	     * @param lastName the household's last name
752	     * @param postcode the household's postcode
753	     * @return the normalized household key
754	     */
755	    private String householdKey(String lastName, String postcode) {
756	        return collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|" + postcode;
757	    }
758	
759	    /**
760	     * Computes the upper-case hex SHA-256 digest of a string, truncated to its first
761	     * {@code hexChars} characters. The input is hashed as UTF-8 bytes and each digest byte is
762	     * rendered as two upper-case hex digits, so {@code hexChars} characters cover the leading
763	     * {@code ceil(hexChars / 2)} bytes of the digest. This is the single definition of the
764	     * SHA-256 hex derivation shared by every rule that hashes owner fields (for example the
765	     * household identifier). SHA-256 is a required platform algorithm; were it ever unavailable
766	     * an {@link IllegalStateException} is thrown.
767	     *
768	     * @param input the string to hash
769	     * @param hexChars the number of leading upper-case hex characters to return
770	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
771	     */
772	    private String shaHex(String input, int hexChars) {
773	        try {
774	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
775	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
776	            StringBuilder sb = new StringBuilder();
777	            for (int i = 0; i < digest.length && sb.length() < hexChars; i++) {
778	                sb.append(String.format("%02X", digest[i]));
779	            }
780	            return sb.substring(0, hexChars);
781	        }
782	        catch (java.security.NoSuchAlgorithmException e) {
783	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
784	        }
785	    }
786	
787	    /**
788	     * Counts the owners that belong to the household identified by the given {@code householdId},
789	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
790	     * of owners, so after a create it reflects the household's size including the newly persisted
791	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
792	     * household and yields {@code 0}.
793	     *
794	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
795	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
796	     */
797	    private int countHouseholdMembers(String householdId) {
798	        if (householdId == null) {
799	            return 0;
800	        }
801	        return (int) this.clinicService.findAllOwners().stream()
802	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
803	            .count();
804	    }
805	
806	    /**
807	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
808	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
809	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
810	     *
811	     * @param value the value to collapse, or {@code null}
812	     * @return the whitespace-collapsed value, never {@code null}
813	     */
814	    private String collapseWhitespace(String value) {
815	        if (value == null) {
816	            return "";
817	        }
818	        return value.trim().replaceAll("\\s+", " ");
819	    }
820	
821	    /**
822	     * Common street-type abbreviations expanded during address normalization, keyed by their
823	     * upper-cased token.
824	     */
825	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
826	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
827	
828	    /**
829	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
830	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
831	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
832	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
833	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
834	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
835	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
836	     * everywhere an address is stored or compared.
837	     *
838	     * @param address the submitted address value, or {@code null}
839	     * @return the normalized address, never {@code null}
840	     */
841	    private String normalizeAddress(String address) {
842	        if (address == null) {
843	            return "";
844	        }
845	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
846	        if (collapsed.isEmpty()) {
847	            return "";
848	        }
849	        String[] tokens = collapsed.split(" ");
850	        StringBuilder sb = new StringBuilder(collapsed.length());
851	        for (int i = 0; i < tokens.length; i++) {
852	            if (i > 0) {
853	                sb.append(' ');
854	            }
855	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
856	        }
857	        return sb.toString();
858	    }
859	}
