17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
32	import org.springframework.security.access.AccessDeniedException;
33	import org.springframework.validation.BindingResult;
34	import org.springframework.validation.FieldError;
35	import org.springframework.web.bind.MethodArgumentNotValidException;
36	import org.springframework.web.bind.annotation.ControllerAdvice;
37	import org.springframework.web.bind.annotation.ExceptionHandler;
38	import org.springframework.web.bind.annotation.ResponseBody;
39	
40	/**
41	 * Global Exception handler for REST controllers.
42	 * <p>
43	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
44	 *
45	 * @author Vitaliy Fedoriv
46	 * @author Alexander Dudkin
47	 */
48	@ControllerAdvice
49	public class ExceptionControllerAdvice {
50	
51	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
52	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
53	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
54	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
55	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the given identity already exists";
56	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
57	    private static final String ERROR_DAILY_LIMIT_EXCEEDED = "The maximum number of owners has already been created today";
58	
59	    /**
60	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
61	     * class.
62	     *
63	     * @param e     Object referring to the thrown exception.
64	     * @param status HTTP response status.
65	     * @param url URL request.
66	     */
67	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
68	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
69	        problemDetail.setType(URI.create(url.toString()));
70	        problemDetail.setTitle(e.getClass().getSimpleName());
71	        problemDetail.setDetail(detail);
72	        problemDetail.setProperty("timestamp", Instant.now());
73	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
74	        return problemDetail;
75	    }
76	
77	    /**
78	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
79	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
80	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
81	     * would catch it and report an authorization failure as a 500.
82	     *
83	     * @param e The {@link AccessDeniedException} to propagate
84	     * @throws AccessDeniedException always
85	     */
86	    @ExceptionHandler(AccessDeniedException.class)
87	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
88	        throw e;
89	    }
90	
91	    /**
92	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
93	     *
94	     * @param e The {@link Exception} to be handled
95	     * @param request {@link HttpServletRequest} object referring to the current request.
96	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
97	     */
98	    @ExceptionHandler(Exception.class)
99	    @ResponseBody
100	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
101	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
102	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
103	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
104	        return ResponseEntity.status(status).body(detail);
105	    }
106	
107	    /**
108	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
109	     * method returns a 404 Not Found status if an entity does not exist.
110	     *
111	     * @param e The {@link DataIntegrityViolationException} to be handled
112	     * @param request {@link HttpServletRequest} object referring to the current request.
113	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
114	     */
115	    @ExceptionHandler(DataIntegrityViolationException.class)
116	    @ResponseBody
117	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
118	        logger.warn("Data integrity violation at {} {}: {}",
119	            request.getMethod(),
120	            request.getRequestURI(),
121	            e.getMessage());
122	        logger.debug("Data integrity violation stacktrace", e);
123	        HttpStatus status = HttpStatus.NOT_FOUND;
124	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
125	        return ResponseEntity.status(status).body(detail);
126	    }
127	
128	    /**
129	     * Handles exception thrown by Bean Validation on controller methods parameters
130	     *
131	     * @param e The {@link MethodArgumentNotValidException} to be handled
132	     * @param request {@link HttpServletRequest} object referring to the current request.
133	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
134	     */
135	    @ExceptionHandler(MethodArgumentNotValidException.class)
136	    @ResponseBody
137	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
138	        HttpStatus status = HttpStatus.BAD_REQUEST;
139	        BindingResult bindingResult = e.getBindingResult();
140	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
141	        if (bindingResult.hasErrors()) {
142	            logger.debug("Validation error at {} {}: {}",
143	                request.getMethod(),
144	                request.getRequestURI(),
145	                bindingResult.getFieldErrors());
146	            detail.setProperty("schemaValidationErrors", schemaValidationErrors(bindingResult));
147	            detail.setProperty("errors", bindingResult.getFieldErrors().stream()
148	                .map(FieldError::getField)
149	                .distinct()
150	                .toList());
151	        }
152	        return ResponseEntity.status(status).body(detail);
153	    }
154	
155	    /**
156	     * Handles {@link RequiredFieldsMissingException} thrown when a request omits or leaves
157	     * blank one or more required fields. Returns a 400 Bad Request whose {@code errors}
158	     * property lists the name of each offending field.
159	     *
160	     * @param e The {@link RequiredFieldsMissingException} to be handled
161	     * @param request {@link HttpServletRequest} object referring to the current request.
162	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
163	     */
164	    @ExceptionHandler(RequiredFieldsMissingException.class)
165	    @ResponseBody
166	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
167	        HttpStatus status = HttpStatus.BAD_REQUEST;
168	        logger.debug("Missing or blank required fields at {} {}: {}",
169	            request.getMethod(),
170	            request.getRequestURI(),
171	            e.getFields());
172	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
173	        detail.setProperty("errors", e.getFields());
174	        return ResponseEntity.status(status).body(detail);
175	    }
176	
177	    /**
178	     * Handles {@link InvalidFieldsException} thrown when a request supplies one or more
179	     * fields whose value is present but fails a business rule (for example a telephone
180	     * that does not normalize to exactly ten digits). Returns a 400 Bad Request whose
181	     * {@code errors} property lists the name of each offending field.
182	     *
183	     * @param e The {@link InvalidFieldsException} to be handled
184	     * @param request {@link HttpServletRequest} object referring to the current request.
185	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
186	     */
187	    @ExceptionHandler(InvalidFieldsException.class)
188	    @ResponseBody
189	    public ResponseEntity<ProblemDetail> handleInvalidFieldsException(InvalidFieldsException e, HttpServletRequest request) {
190	        HttpStatus status = HttpStatus.BAD_REQUEST;
191	        logger.debug("Invalid field values at {} {}: {}",
192	            request.getMethod(),
193	            request.getRequestURI(),
194	            e.getFields());
195	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
196	        detail.setProperty("errors", e.getFields());
197	        return ResponseEntity.status(status).body(detail);
198	    }
199	
200	    /**
201	     * Handles {@link DuplicateIdentityException} thrown when a request tries to create an owner
202	     * whose derived identity key (normalized telephone, email and household identifier) is already
203	     * used by another owner. Returns a 409 Conflict.
204	     *
205	     * @param e The {@link DuplicateIdentityException} to be handled
206	     * @param request {@link HttpServletRequest} object referring to the current request.
207	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
208	     */
209	    @ExceptionHandler(DuplicateIdentityException.class)
210	    @ResponseBody
211	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
212	        HttpStatus status = HttpStatus.CONFLICT;
213	        logger.debug("Duplicate identity at {} {}: {}",
214	            request.getMethod(),
215	            request.getRequestURI(),
216	            e.getMessage());
217	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_IDENTITY);
218	        return ResponseEntity.status(status).body(detail);
219	    }
220	
221	    /**
222	     * Handles {@link CityCapacityExceededException} thrown when a request tries to create an owner
223	     * whose city already contains the maximum number of owners. Returns a 409 Conflict.
224	     *
225	     * @param e The {@link CityCapacityExceededException} to be handled
226	     * @param request {@link HttpServletRequest} object referring to the current request.
227	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
228	     */
229	    @ExceptionHandler(CityCapacityExceededException.class)
230	    @ResponseBody
231	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
232	        HttpStatus status = HttpStatus.CONFLICT;
233	        logger.debug("City at capacity at {} {}: {}",
234	            request.getMethod(),
235	            request.getRequestURI(),
236	            e.getMessage());
237	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
238	        return ResponseEntity.status(status).body(detail);
239	    }
240	
241	    /**
242	     * Handles {@link DailyOwnerLimitExceededException} thrown when a request tries to create an owner
243	     * once the maximum number of owners for the current day has already been created. Returns a
244	     * 429 Too Many Requests.
245	     *
246	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
247	     * @param request {@link HttpServletRequest} object referring to the current request.
248	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
249	     */
250	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
251	    @ResponseBody
252	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
253	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
254	        logger.debug("Daily owner limit exceeded at {} {}: {}",
255	            request.getMethod(),
256	            request.getRequestURI(),
257	            e.getMessage());
258	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT_EXCEEDED);
259	        return ResponseEntity.status(status).body(detail);
260	    }
261	
262	    /**
263	     * Renders the field-level errors of a {@link BindingResult} as the {@link ValidationMessageDto} list
264	     * exposed under the {@code schemaValidationErrors} property of the response.
265	     *
266	     * @param bindingResult The {@link BindingResult} carrying the rejected fields.
267	     * @return One {@link ValidationMessageDto} per field error.
268	     */
269	    private List<ValidationMessageDto> schemaValidationErrors(BindingResult bindingResult) {
270	        return bindingResult.getFieldErrors().stream()
271	            .map(fieldError -> {
272	                String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
273	                String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
274	                String message = "Field '%s' %s (rejected value: %s)".formatted(
275	                    fieldError.getField(),
276	                    defaultMessage,
277	                    rejectedValue);
278	                return new ValidationMessageDto(message)
279	                    .putAdditionalProperty("field", fieldError.getField())
280	                    .putAdditionalProperty("rejectedValue", rejectedValue)
281	                    .putAdditionalProperty("defaultMessage", defaultMessage);
282	            })
283	            .toList();
284	    }
285	
286	}
